CREATE TABLE IF NOT EXISTS family_statuses(id INT PRIMARY KEY AUTO_INCREMENT,family_id INT NOT NULL UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'active',note VARCHAR(1000) NOT NULL DEFAULT '',updated_at VARCHAR(30) NOT NULL,revision INT NOT NULL DEFAULT 0,CONSTRAINT family_status_family_fk FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS family_invites(id INT PRIMARY KEY AUTO_INCREMENT,family_id INT NOT NULL,label VARCHAR(200) NOT NULL DEFAULT '',url VARCHAR(2000) NOT NULL,sent_on VARCHAR(10) NOT NULL DEFAULT '',revision INT NOT NULL DEFAULT 0,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,sent_at VARCHAR(32) NOT NULL DEFAULT '',retired_at VARCHAR(32) NOT NULL DEFAULT '',recipients VARCHAR(3000) NOT NULL DEFAULT '',KEY family_invites_family(family_id),CONSTRAINT family_invite_family_fk FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS member_moves(id INT PRIMARY KEY AUTO_INCREMENT,member_id INT NULL,email VARCHAR(254) NOT NULL,customer_name VARCHAR(200) NOT NULL,from_family_id INT NULL,from_family_name VARCHAR(200) NOT NULL,from_status VARCHAR(20) NOT NULL,from_note VARCHAR(1000) NOT NULL,to_family_id INT NULL,to_family_name VARCHAR(200) NOT NULL,invite_id INT NULL,invite_label VARCHAR(200) NOT NULL DEFAULT '',state VARCHAR(20) NOT NULL DEFAULT 'assigned',report_reason VARCHAR(30) NOT NULL DEFAULT '',report_note VARCHAR(500) NOT NULL DEFAULT '',created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,opened_at VARCHAR(30) NOT NULL DEFAULT '',joined_at VARCHAR(30) NOT NULL DEFAULT '',reported_at VARCHAR(30) NOT NULL DEFAULT '',dismissed_at VARCHAR(30) NOT NULL DEFAULT '',revision INT NOT NULL DEFAULT 0,KEY member_moves_member(member_id),KEY member_moves_invite(invite_id),CONSTRAINT member_move_member_fk FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL,CONSTRAINT member_move_from_fk FOREIGN KEY(from_family_id) REFERENCES families(id) ON DELETE SET NULL,CONSTRAINT member_move_to_fk FOREIGN KEY(to_family_id) REFERENCES families(id) ON DELETE SET NULL,CONSTRAINT member_move_invite_fk FOREIGN KEY(invite_id) REFERENCES family_invites(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS lookup_codes(id INT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(254) NOT NULL UNIQUE,code VARCHAR(16) NOT NULL,created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS lookup_settings(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE,value VARCHAR(1000) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS lookup_sessions(token_hash VARCHAR(64) PRIMARY KEY,email VARCHAR(254) NOT NULL,expires_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS lookup_attempts(name VARCHAR(200) PRIMARY KEY,window_end BIGINT NOT NULL,count INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS invite_mails(id INT PRIMARY KEY AUTO_INCREMENT,family_id INT NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,created_at VARCHAR(30) NOT NULL,KEY invite_mails_family(family_id),CONSTRAINT invite_mail_family_fk FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS customer_reports(id INT PRIMARY KEY AUTO_INCREMENT,member_id INT NULL,email VARCHAR(254) NOT NULL,family_id INT NULL,family_name VARCHAR(200) NOT NULL,reason VARCHAR(30) NOT NULL,note VARCHAR(500) NOT NULL DEFAULT '',created_at VARCHAR(30) NOT NULL,handled_at VARCHAR(30) NOT NULL DEFAULT '',handled_note VARCHAR(500) NOT NULL DEFAULT '',revision INT NOT NULL DEFAULT 0,KEY customer_reports_member(member_id),KEY customer_reports_family(family_id),CONSTRAINT customer_report_member_fk FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL,CONSTRAINT customer_report_family_fk FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS todos(id INT PRIMARY KEY AUTO_INCREMENT,text VARCHAR(1200) NOT NULL,due_on VARCHAR(10) NOT NULL DEFAULT '',done_at VARCHAR(32) NOT NULL DEFAULT '',created_at VARCHAR(32) NOT NULL,updated_at VARCHAR(32) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
